def resolve(path, cwd, links):
    if not isinstance(path, str) or not isinstance(cwd, str) or not isinstance(links, dict):
        return None

    if not cwd or cwd[0] != '/':
        return None

    # Normalize cwd: remove trailing slash except for root
    if cwd != '/' and cwd.endswith('/'):
        cwd = cwd.rstrip('/')

    # Start with cwd if path is relative
    if not path or path[0] != '/':
        current = cwd
    else:
        current = ''

    # Split path into components
    components = path.split('/')
    link_count = 0

    i = 0
    while i < len(components):
        comp = components[i]
        i += 1

        # Skip empty and '.' components
        if comp == '' or comp == '.':
            continue

        # Handle '..'
        if comp == '..':
            if current == '/':
                continue
            # Move to parent
            last_slash = current.rfind('/')
            if last_slash == 0:
                current = '/'
            else:
                current = current[:last_slash]
            continue

        # Regular component: append it
        if current == '/':
            current = '/' + comp
        else:
            current = current + '/' + comp

        # Check if current path is a symlink
        if current in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[current]

            # Process the target
            if target[0] == '/':
                # Absolute target: restart from root
                current = ''
                target_components = target.split('/')
            else:
                # Relative target: resolve relative to the directory containing the link
                last_slash = current.rfind('/')
                if last_slash == 0:
                    current = '/'
                else:
                    current = current[:last_slash]
                target_components = target.split('/')

            # Insert remaining components from current path after target components
            components = target_components + components[i:]
            i = 0

    # Remove trailing slash except for root
    if current == '':
        return '/'
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

